import Base
import ../owned.bend as A
def finish(-P: Type, result: P & U32) -> P & String:
  match result:
    case (p, x): (p, U32.show(x))
def callback(-P: Type, get: P -> A.Motion -> P & U32, p: P) -> P & String:
  finish(P, get(p, A.Motion{}))
def main() -> A.Store<A.Motion> & String:
  A.read(~A.Motion, ~callback, 0, A.initial(~A.Motion))

